function FloatingNotes({ notes, inverted = false }) {
  return (
    <div className={`${styles.floats} ${inverted ? styles.floatsInverted : ''}`} aria-hidden="true">
      {notes.map((n, i) => (
        <span
          key={i}
          className={styles.floatNote}
          style={{ top: n.top, left: n.left, fontSize: n.size, opacity: n.opacity, transform: `rotate(${n.rot}deg)` }}
        >
          {n.glyph}
        </span>
      ))}
    </div>
  )
}

